/* a part you can touch: while it is on, everything else steps back and the note under the card changes */
let partN = 0;
function PT(note,fn,{lift,ring = false,tag = '',deco = false} = {}){ out.push(`<g class="p${ring ? ' rg' : ''}${deco ? ' deco' : ''}" tabindex="0" role="button" aria-label="${esc(note)}" data-n="${esc(note)}"${lift ? ` style="--dx:${lift[0]}px;--dy:${lift[1]}px"` : ''}${tag}>`); fn(); out.push('</g>'); }
/* loops gently forever; class picks the movement in the page CSS */
const MOVE = (cls,fn,delay = 0) => { out.push(`<g class="mv ${cls}" style="animation-delay:${delay.toFixed(2)}s">`); fn(); out.push('</g>'); };
const hair = (a,b,o = .9) => rule([[a,b]],'#b6ae9f',o);
const dashed = (a,b) => dash(a,b,LN);
const AX = (x0,y0,x1,y1) => { ink([[x0,y0],[x0,y1],[x1,y1]],1.2,{over:0}); };
const stem = (a,b,w = 1.1,col = INK) => line([a,b],{w,col,over:0});
const iso = (x,y,fn) => { const a = OX, b = OY; OX = x; OY = y; fn(); OX = a; OY = b; };
const mix = mixC;
/* a slice of something round and thick, in iso. Angles are real, so a slice's share stays true. */
function wedge(r,a0,a1,h,top,side,{z = 0,rim = null,rimW = .13,crimp = 0} = {}){
  const n = Math.max(6,Math.round((a1-a0)/6)), A = i => (a0+(a1-a0)*i/n)*Math.PI/180, pt = (rr,t,zz) => P(rr*Math.cos(t),rr*Math.sin(t),zz);
  const faces = (t) => { const q = [P(0,0,z),pt(r,t,z),pt(r,t,z+h),P(0,0,z+h)]; flat(q,shadeOf(side)); rim_(q); };
  const rim_ = q => rim2(q,.8);
  faces(a0*Math.PI/180); faces(a1*Math.PI/180);
  let seg = []; for (let i = 0; i <= n; i++){ const t = A(i); if (Math.cos(t)+Math.sin(t) > -.02) seg.push(t); }
  if (seg.length > 1){ const lo = seg.map(t => pt(r,t,z)), hi = seg.map(t => pt(r,t,z+h)); flat([...lo,...hi.reverse()],side); line(lo,{w:1,over:0}); }
  const arc = Array.from({length:n+1},(_,i) => pt(r,A(i),z+h)), T = [P(0,0,z+h),...arc]; flat(T,top);
  if (rim){ const inn = Array.from({length:n+1},(_,i) => pt(r*(1-rimW),A(i),z+h)); flat([...arc,...[...inn].reverse()],rim); line(inn,{w:.7,over:0,col:trim(rim)}); for (let d = Math.ceil(a0/crimp)*crimp; d < a1; d += crimp){ const t = d*Math.PI/180; rule([[pt(r*(1-rimW*.8),t,z+h),pt(r,t,z+h)]],trim(rim),.8); } }
  lid(T,1.2);
}
const rim2 = (pts,w,col = INK) => rim(pts,w,col);
/* small objects that stand in where a person used to: each one sits with its base on (x,y) */
const spin = (pts,x,y,deg) => { const t = deg*Math.PI/180, c = Math.cos(t), n = Math.sin(t); return pts.map(([a,b]) => [x+(a-x)*c-(b-y)*n, y+(a-x)*n+(b-y)*c]); };
function propCup(x,y,s = 1){ const p = (a,b) => [x+a*s,y+b*s], body = [p(-8,-30),p(8,-30),p(6,0),p(-6,0)], sleeve = [p(-7.3,-20),p(7.3,-20),p(6.7,-10),p(-6.7,-10)], cap = [p(-10,-34),p(10,-34),p(9,-29.5),p(-9,-29.5)];
  wash(body,'#fdf9f1',{dx:0,dy:0}); wash(sleeve,'#c3ab86',{dx:0,dy:0}); lid(body,1.1); rule([[sleeve[0],sleeve[1]],[sleeve[3],sleeve[2]]],'#a7916e',.7);
  wash(cap,'#efece6',{dx:0,dy:0}); lid(cap,1); wash([p(-5,-34),p(5,-34),p(4,-36.5),p(-4,-36.5)],'#efece6',{dx:0,dy:0}); lid([p(-5,-34),p(5,-34),p(4,-36.5),p(-4,-36.5)],.8); }
function propJug(x,y,s = 1){ const p = (a,b) => [x+a*s,y+b*s], body = [p(-9,-28),p(7,-28),p(9,-4),p(7,0),p(-7,0),p(-9,-4)], lip = [p(7,-28),p(13,-32),p(9,-24)];
  wash(body,'#c7cbcd',{dx:0,dy:0}); wash(lip,'#c7cbcd',{dx:0,dy:0}); lid([...body.slice(0,1),...lip,...body.slice(2)],1.1);
  wash([p(-6,-26),p(-3,-26),p(-3,-3),p(-6,-3)],'#e1e4e6',{dx:0,dy:0}); ink(bend(p(-9,-22),p(-17,-15),p(-9,-7)),1.6,{over:0}); rule([[p(-9,-14),p(9,-14)]],'#9fa5a8',.6); }
function propPack(x,y,s = 1){ const p = (a,b) => [x+a*s,y+b*s], body = spline([p(-11,0),p(11,0),p(12,-18),p(8,-30),p(-8,-30),p(-12,-18)],true,2), flap = spline([p(-9,-29),p(9,-29),p(10,-19),p(0,-16),p(-10,-19)],true,2), pocket = [p(-7,-11),p(7,-11),p(7,-3),p(-7,-3)];
  wash(body,'#d08f7a',{dx:0,dy:0}); lid(body,1.1); wash(flap,'#bf8270',{dx:0,dy:0}); lid(flap,.9); wash(pocket,'#bf8270',{dx:0,dy:0}); lid(pocket,.8);
  ink(bend(p(-5,-30),p(0,-37),p(5,-30)),1.3,{over:0}); out.push(`<circle cx="${n1(x)}" cy="${n1(y-17*s)}" r="${n1(1.3*s)}" fill="#e0c698"/>`); }
function propSled(x,y,s = 1,deg = 0){ const p = (a,b) => [x+a*s,y+b*s], R = v => spin(v,x,y,deg), seat = R([p(-15,-9),p(15,-9),p(15,-5),p(-15,-5)]);
  ink(R(bend(p(-18,0),p(20,0),p(22,-8))),1.5,{over:0,col:'#8e7f6c'}); for (const a of [-10,10]) ink(R([p(a,-1),p(a,-6)]),1.1,{over:0,col:'#8e7f6c'});
  wash(seat,'#d6826d',{dx:0,dy:0}); lid(seat,1); ink(R(bend(p(14,-9),p(22,-16),p(26,-10))),.8,{over:0,col:'#9b9286'}); }
function propBoard(x,y,s = 1,deg = 0){ const p = (a,b) => [x+a*s,y+b*s], R = v => spin(v,x,y,deg), board = R(spline([p(-24,-2),p(0,-5.5),p(24,-2.5),p(26,-1),p(0,1.5),p(-23,0)],true,2));
  wash(board,'#e8ca89',{dx:0,dy:0}); lid(board,1.1); ink(R([p(-20,-1.4),p(22,-1.6)]),.7,{over:0,col:'#d08f7a'}); wash(R([p(-17,1),p(-12,1),p(-15,6)]),'#7c96b1',{dx:0,dy:0}); }
function propSeat(x,y0,y1,s = 1){ const p = (a,b) => [x+a*s,b], seat = [p(-9,y1),p(9,y1),p(8,y1+4),p(-8,y1+4)];
  stem([x,y0],p(-8,y1),.8,'#9b9286'); stem([x,y0],p(8,y1),.8,'#9b9286'); wash(seat,'#d6826d',{dx:0,dy:0}); lid(seat,1); }
/* the solid bits that stand beside a chart */
function potted(x,y,s = 1){ const p = (a,b) => [x+a*s,y+b*s], body = [p(-24,-30),p(24,-30),p(18,6),p(-18,6)];
  for (const [a,L,wd,col] of [[-2.3,50,12,WASH.sage],[-1.25,62,12,'#8abba3'],[-.75,46,11,WASH.sage],[-1.85,60,12,'#97c4ad'],[-.35,36,9,WASH.sage]]) leaf(p(0,-30),a,L*s,wd*s,col);
  wash(body,'#d08f7a'); lid(body); const r = [p(-28,-38),p(28,-38),p(28,-29),p(-28,-29)]; wash(r,'#da9e8a'); lid(r); }
const CUP = (x,y,s = 1,col = '#f2e9d6',fillc = '#a16b55') => { const p = (a,b) => [x+a*s,y+b*s], b = [p(-15,-16),p(15,-16),p(11,4),p(-11,4)]; wash(b,col); lid(b); ink(bend(p(15,-12),p(28,-8),p(13,-1)),1.1,{over:0}); const t = ringAt((a,c) => p(15*a,-16+3.6*c),16); wash(t,fillc,{dx:0,dy:0}); lid(t,1); };
const STEAM = (x,y,n = 2) => { for (let i = 0; i < n; i++) MOVE('steam',() => ink(bend([x+i*9,y],[x+i*9+6,y-10],[x+i*9,y-20]),.9,{over:0}),i*.5); };
const SPARK = (x,y,r = 5) => { plus(x,y,r); };

const sector = (cx,cy,r0,r1,a0,a1) => { const n = Math.max(4,Math.round((a1-a0)/5)), A = i => (a0+(a1-a0)*i/n)*Math.PI/180, o = []; for (let i = 0; i <= n; i++) o.push([cx+r1*Math.cos(A(i)),cy+r1*Math.sin(A(i))]); for (let i = n; i >= 0; i--) o.push([cx+r0*Math.cos(A(i)),cy+r0*Math.sin(A(i))]); return o; };
const smooth = (pts,step = 5) => spline(pts,false,step);
const face = (x,y,r,mood) => { DC(x,y,r,'',{col:'#efdbb4'}); out.push(`<circle cx="${x-r*.34}" cy="${y-r*.15}" r="1.4" fill="${INK}"/><circle cx="${x+r*.34}" cy="${y-r*.15}" r="1.4" fill="${INK}"/>`); const m = mood*r*.4; ink(bend([x-r*.42,y+r*.32],[x,y+r*.32+m],[x+r*.42,y+r*.32]),1,{over:0}); };

/* a step you can touch: the red pen rings it */
const STEP = (note,fn) => { let b; PT(note,() => { b = fn(); },{ring:true}); return b; };

/* a neat label line: steady ink, a small open ring at the label and a dot on the thing */
/* the bend always sits between label and thing, so the line never runs past its target and doubles back (sx is kept for old calls, the direction comes from the points) */
function lead(a,b,sx){ const k = LOOSE; LOOSE = 0; sx = Math.sign(b[0]-a[0]) || sx; const e = [b[0]-sx*Math.min(30,Math.abs(b[0]-a[0])*.4),a[1]]; line(Math.abs(b[1]-a[1]) < 3 ? [a,b] : [a,e,b],{w:.85,col:LN,over:0}); LOOSE = k; out.push(`<circle cx="${n1(a[0])}" cy="${n1(a[1])}" r="2.6" fill="${PAPER}" stroke="${LN}" stroke-width=".9"/><circle cx="${n1(b[0])}" cy="${n1(b[1])}" r="1.9" fill="${INK}"/>`); }
